\section{Setting and definitions}

Throughout, $r \ge 1$ and $M \ge 0$ are integers and $\Z/r\Z$ is written additively as the
cycle $\{0,1,\dots,r-1\}$. Logarithms in complexity statements are base $2$.

\begin{definition}[Circle distance]
For integers $r>0$ and $x \ge 0$ set
$d_r(x) = \min\bigl(x \bmod r,\; r - (x \bmod r)\bigr)$.
Thus $0 \le d_r(x) \le r/2$, and $d_r(x) = 0$ iff $r \mid x$.
\end{definition}

\begin{definition}[Lacunary dyadic Cayley graph]
The graph $\mathcal C(r,M)$ is the Cayley graph of $\Z/r\Z$ with the multiset of
$2(M+1)$ generators $S_M = \{+2^t, -2^t : 0 \le t \le M\}$. The simple random walk on
$\mathcal C(r,M)$ chooses a generator uniformly from $S_M$.
\end{definition}

\begin{definition}[Half-lazy diffusion operator]
For $f : \Z \to \C$ (identified with an $r$-periodic function on the cycle),
\[
(W_M f)(x) \;=\; \frac{f(x)}{2}
  \;+\; \frac{1}{4(M+1)}\sum_{t=0}^{M}\bigl(f(x+2^t) + f(x-2^t)\bigr).
\]
This is $W = \tfrac12(I+P)$ with $P$ the transition operator of the simple random walk on
$\mathcal C(r,M)$.
\end{definition}

\begin{definition}[Characters and eigenvalues]
For $0 \le k < r$ let $\chi_k(x) = \exp(2\pi i k x / r)$, and set
\[
\lambda_k(r,M) = \frac{1}{M+1}\sum_{t=0}^{M}\cos\Bigl(\frac{2\pi k 2^t}{r}\Bigr),
\qquad
\mu_k(r,M) = \frac{1+\lambda_k(r,M)}{2}.
\]
\end{definition}

\begin{definition}[Heat kernel at the identity; periodic delta]
For $n \ge 0$, $\displaystyle p_n(r,M) = \frac1r\sum_{k=0}^{r-1}\mu_k(r,M)^n$; and
$\delta_r(x) = 1$ if $r \mid x$, else $0$.
\end{definition}

Proposition~\ref{prop:return} below justifies the name: $p_n(r,M) = (W_M^n\delta_r)(0)$,
the probability that the half-lazy walk started at the identity is at the identity after
$n$ steps.

\section{The doubling lemma}\label{sec:doubling}

The following statements are the combinatorial engine of the paper; they involve no
analysis.

\begin{lemma}[Positivity]\label{lem:pos}
If $r>0$ and $x \not\equiv 0 \pmod r$ then $d_r(x) > 0$.
\end{lemma}
\begin{proof}
With $s = x \bmod r$ we have $0 < s < r$, so both $s$ and $r-s$ are positive.
\end{proof}

\begin{lemma}[Doubling step]\label{lem:double}
Let $r>0$ and $x \ge 0$ satisfy $4 d_r(x) < r$. Then $d_r(2x) = 2 d_r(x)$.
\end{lemma}
\begin{proof}
Put $s = x \bmod r \in [0,r)$, so $(2x)\bmod r = (2s)\bmod r$.

\emph{Case 1: $2s < r$.} Then $(2x) \bmod r = 2s$ and $d_r(2x) = \min(2s, r-2s)$. If
$\min(s,r-s) = s$ then $4s < r$, so $2s < r-2s$ and $d_r(2x) = 2s = 2d_r(x)$. If
$\min(s,r-s) = r-s$ then $4(r-s) < r$, whence $s > 3r/4$ and $2s > 3r/2 > r$, contradicting
the case assumption; that subcase is vacuous.

\emph{Case 2: $2s \ge r$.} Then $(2x)\bmod r = 2s-r$, and $s \ge r/2$ forces
$\min(s,r-s) = r-s =: u$ with $4u < r$. Since $2s - r = r-2u$,
\[
d_r(2x) = \min(r-2u,\; 2u) = 2u = 2 d_r(x),
\]
because $2u < r/2 < r-2u$.
\end{proof}

In both cases doubling cannot wrap past the antipode, precisely because
$2 d_r(x) < r/2$.

\begin{lemma}[Iterated doubling]\label{lem:iter}
Let $r>0$, $x \not\equiv 0 \pmod r$, and suppose $4 d_r(2^t x) < r$ for every $t \le M$.
Then $d_r(2^t x) = 2^t d_r(x)$ for all $t \le M$.
\end{lemma}
\begin{proof}
Induction on $t$; the base case is trivial and the inductive step is
Lemma~\ref{lem:double} applied at the point $2^t x$.
\end{proof}

\begin{theorem}[Doubling lemma]\label{thm:doubling}
Let $r>0$, $k \not\equiv 0 \pmod r$, and $r \le 2^M$. Then there is $t \le M$ with
$r \le 4 d_r(2^t k)$, i.e.\ $2^t k \bmod r$ lies in the far arc $[r/4, 3r/4]$.
\end{theorem}
\begin{proof}
Otherwise $4 d_r(2^t k) < r$ for all $t \le M$, and Lemma~\ref{lem:iter} gives
$d_r(2^M k) = 2^M d_r(k) \ge 2^M \ge r$ by Lemma~\ref{lem:pos}. Then
$4 d_r(2^M k) \ge 4r > r$, contradicting the assumption at $t=M$.
\end{proof}

\begin{remark}
Any generating set forming a geometric progression of ratio $\ge 2$ whose largest element
exceeds $r$ admits the same escape argument: ``staying near the origin'' is a geometrically
expanding, hence self-defeating, hypothesis.
\end{remark}

\section{From the far arc to a spectral gap}\label{sec:gap}

\begin{lemma}[Nonpositive cosine]\label{lem:cos}
If $r>0$, $x \ge 0$ and $r \le 4 d_r(x)$, then $\cos(2\pi x/r) \le 0$.
\end{lemma}
\begin{proof}
With $s = x \bmod r$, the hypothesis gives $r \le 4s$ and $4s \le 3r$, i.e.\
$s \in [r/4, 3r/4]$. The angle $2\pi x/r$ differs from $2\pi s/r$ by an integer multiple of
$2\pi$, and $2\pi s/r \in [\pi/2, 3\pi/2]$, where $\cos \le 0$.
\end{proof}

\begin{theorem}[Spectral gap]\label{thm:gap}
Let $r>0$, $k \not\equiv 0 \pmod r$ and $r \le 2^M$. Then
$\lambda_k(r,M) \le 1 - \frac{1}{M+1}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:doubling} choose $t_0 \le M$ with $r \le 4 d_r(2^{t_0}k)$; by
Lemma~\ref{lem:cos} the $t_0$-th summand of $(M+1)\lambda_k$ is $\le 0$, while each of the
remaining $M$ summands is $\le 1$. Hence $(M+1)\lambda_k \le M$.
\end{proof}

\begin{corollary}[Half-lazy spectrum]\label{cor:lazy}
Under the hypotheses of Theorem~\ref{thm:gap},
$0 \le \mu_k(r,M) \le 1 - \frac{1}{2(M+1)} =: \beta_M$. Moreover $\mu_0 = 1$ and
$0 \le \mu_k \le 1$ for every $k$.
\end{corollary}
\begin{proof}
All cosines lie in $[-1,1]$, so $-1 \le \lambda_k \le 1$ and $0 \le \mu_k \le 1$; the
trivial character has all cosines $1$, so $\mu_0 = 1$. The upper bound is
Theorem~\ref{thm:gap} together with $\mu_k = \tfrac12(1+\lambda_k)$.
\end{proof}

Laziness is essential: without it $\lambda_k$ could approach $-1$ (a bipartite-type
obstruction) and $|\lambda_k|^n$ would not decay. Half-laziness costs a factor $2$ in the
gap and buys nonnegativity of the entire spectrum.

\section{Two-sided bounds on the heat kernel}\label{sec:bounds}

\begin{theorem}[Lower bound]\label{thm:low}
For all $r>0$, $M$, $n$: $\; \frac1r \le p_n(r,M)$.
\end{theorem}
\begin{proof}
$r p_n = \mu_0^n + \sum_{k\ne0}\mu_k^n = 1 + \sum_{k \ne 0}\mu_k^n \ge 1$, since all
$\mu_k \ge 0$ by Corollary~\ref{cor:lazy}.
\end{proof}

\begin{theorem}[Upper bound]\label{thm:up}
Let $0 < r \le 2^M$. Then $p_n(r,M) \le \frac1r + \beta_M^n$ for all $n$.
\end{theorem}
\begin{proof}
Every $k \in \{1,\dots,r-1\}$ has $k \not\equiv 0 \pmod r$, so $0 \le \mu_k \le \beta_M$ and
$\mu_k^n \le \beta_M^n$. Hence $r p_n \le 1 + (r-1)\beta_M^n \le 1 + r\beta_M^n$.
\end{proof}

The return probability is thus a \emph{one-sided} estimator of $1/r$: it never undershoots,
and its overshoot is the $n$-th power of the gap. One-sidedness makes the rounding argument
clean.

\section{Mixing time and exact recovery}\label{sec:recovery}

\begin{lemma}[Mixing at $n = 8(M+1)^2$]\label{lem:mix}
If $0 < N \le 2^M$ then $\beta_M^{\,8(M+1)^2} \le \frac{1}{4N^2}$.
\end{lemma}
\begin{proof}
Write $D = M+1 \ge 1$, so $\beta_M = 1 - \frac{1}{2D} \in [0,1]$. From $1+u \le e^u$ at
$u = -\frac{1}{2D}$,
\[
\beta_M^{\,8D^2} \le \exp\Bigl(-\frac{8D^2}{2D}\Bigr) = e^{-4D}.
\]
Also $4 \le e^4$, so $e^{4D} = (e^4)^{M+1} \ge 4^{M+1} = 4\cdot 4^M = 4(2^M)^2 \ge 4N^2$.
\end{proof}

\begin{lemma}[Rounding]\label{lem:round}
Let $r>0$, $\varepsilon \ge 0$ and $\frac1r \le p \le \frac1r + \varepsilon$ with
$2r^2\varepsilon < 1$. Then $\round{1/p} = r$.
\end{lemma}
\begin{proof}
Since $p \ge 1/r > 0$ we get $1/p \le r$. Also $p \le \frac{1+r\varepsilon}{r}$ gives
\[
\frac1p \;\ge\; \frac{r}{1+r\varepsilon}
       \;=\; r\Bigl(1 - \frac{r\varepsilon}{1+r\varepsilon}\Bigr)
       \;>\; r - r^2\varepsilon \;>\; r - \tfrac12 .
\]
Thus $1/p \in (r-\tfrac12, r]$, which rounds to $r$.
\end{proof}

\begin{theorem}[Heat-kernel order recovery]\label{thm:main}
Let $0 < r \le N \le 2^M$ and $n = 8(M+1)^2$. Then
\[
\round*{\frac{1}{p_n(r,M)}} \;=\; r .
\]
\end{theorem}
\begin{proof}
Theorems~\ref{thm:low} and~\ref{thm:up} give
$\frac1r \le p_n \le \frac1r + \beta_M^n$, and Lemma~\ref{lem:mix} gives
$\beta_M^n \le \varepsilon := \frac{1}{4N^2}$. Since $r \le N$,
$2r^2\varepsilon = \frac{r^2}{2N^2} \le \frac12 < 1$, so Lemma~\ref{lem:round} applies.
\end{proof}

\begin{corollary}[Multiplicative order]
Let $b \in (\Z/N\Z)^\times$ with $r = \ord_N(b)$, let $N \le 2^M$ and $n = 8(M+1)^2$.
Then $\round{1/p_n(r,M)} = r$.
\end{corollary}
\begin{proof}
By Lagrange $r \mid \varphi(N) \le N$ and $r \ge 1$, so Theorem~\ref{thm:main} applies.
\end{proof}

The proof needs $2r^2\varepsilon < 1$ and delivers $2r^2\varepsilon \le \tfrac12$: the
constant $8$ in the step count is therefore not tight
(cf.\ Conjecture~\ref{conj:def}).

\section{Operational grounding}\label{sec:operational}

Without this section the recovery statement would be open to a charge of circularity, since
$p_n$ was defined by a spectral formula referring to $r$.

\begin{lemma}[Characters are eigenvectors]\label{lem:eig}
$W_M \chi_k = \mu_k(r,M)\,\chi_k$ for all $r,M,k$.
\end{lemma}
\begin{proof}
From $\chi_k(x \pm m) = \chi_k(x)\chi_k(\pm m)$ and
$\chi_k(m)+\chi_k(-m) = 2\cos(2\pi k m/r)$,
\[
(W_M\chi_k)(x) = \chi_k(x)\Bigl[\frac12 + \frac{1}{4(M+1)}\sum_{t=0}^{M}
   2\cos\Bigl(\frac{2\pi k2^t}{r}\Bigr)\Bigr] = \chi_k(x)\,\frac{1+\lambda_k}{2}. \qedhere
\]
\end{proof}

\begin{lemma}[Character orthogonality]\label{lem:orth}
For $r>0$ and $x \in \Z$, $\sum_{k=0}^{r-1}\chi_k(x) = r\,\delta_r(x)$.
\end{lemma}
\begin{proof}
Put $\omega = e^{2\pi i x/r}$, so $\chi_k(x) = \omega^k$. If $r \mid x$ then $\omega = 1$
and the sum is $r$; otherwise $\omega \ne 1$, $\omega^r = 1$, and the geometric sum is
$(\omega^r-1)/(\omega-1) = 0$.
\end{proof}

\begin{proposition}[Heat kernel $=$ return probability]\label{prop:return}
For $r>0$ and all $M,n$: $\;(W_M^n\delta_r)(0) = p_n(r,M)$.
\end{proposition}
\begin{proof}
By Lemma~\ref{lem:orth}, $\delta_r = \frac1r\sum_{k<r}\chi_k$. Linearity of $W_M$ and
Lemma~\ref{lem:eig} iterated give $W_M^n\chi_k = \mu_k^n\chi_k$; evaluating at $x=0$, where
$\chi_k(0)=1$, yields $\frac1r\sum_{k<r}\mu_k^n = p_n(r,M)$.
\end{proof}

\begin{theorem}[Operational order recovery]
Let $0 < r \le N \le 2^M$. Then
$\round*{1/\bigl(W_M^{\,8(M+1)^2}\delta_r\bigr)(0)} = r$.
\end{theorem}
\begin{proof}
Combine Proposition~\ref{prop:return} with Theorem~\ref{thm:main}.
\end{proof}

The operator $W_M$ is a genuine stochastic diffusion: its coefficients are nonnegative and
sum to $\tfrac12 + 2(M+1)\cdot\frac{1}{4(M+1)} = 1$. Its definition mentions only $M$; the
order $r$ enters solely through the periodicity of the state space --- exactly the situation
of an experimenter who knows the bit-length of $N$ but not the order.

\section{Rigidity and multiplicativity of the witness value}\label{sec:rigidity}

\begin{theorem}[Rigidity]
Fix $M$, $N \le 2^M$, $n = 8(M+1)^2$. If $0 < r_1, r_2 \le N$ and
$p_n(r_1,M) = p_n(r_2,M)$ then $r_1 = r_2$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:main} gives $r_i = \round{1/p_n(r_i,M)}$; equal values round equally.
\end{proof}

Thus on the whole admissible range the heat-kernel value is a \emph{complete invariant} of
the order, not merely a good estimator.

\begin{theorem}[Approximate multiplicativity]\label{thm:mult}
Let $0 < r_1, r_2$ with $r_1, r_2, r_1r_2 \le N \le 2^M$ and $n = 8(M+1)^2$. Then
\[
\bigl|p_n(r_1r_2,M) - p_n(r_1,M)p_n(r_2,M)\bigr| \;\le\; \frac{1}{N^2}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Each of the three values lies within $\varepsilon = \frac{1}{4N^2}$ above the corresponding
reciprocal. Writing $p_n(r_i,M) = \frac{1}{r_i} + \theta_i\varepsilon$ and
$p_n(r_1r_2,M) = \frac{1}{r_1r_2}+\theta_0\varepsilon$ with $\theta_j \in [0,1]$, expanding
the product and using $r_i \ge 1$, $\varepsilon \le \tfrac14$ bounds the difference by
$\varepsilon(1+1+1+\varepsilon) \le 4\varepsilon = 1/N^2$.
\end{proof}

\begin{remark}[An honest correction]
Theorem~\ref{thm:mult} refutes the tempting slogan that the heat-kernel witness is a
\emph{non-multiplicative} invariant of the order: as a function of $r$ the witness value is
$1/r$ up to $O(N^{-2})$, and $r \mapsto 1/r$ is completely multiplicative. What is genuinely
non-multiplicative is the \emph{mechanism} producing the value --- a spectral aggregate over
all $r$ eigenvalues of a graph determined by the ambient modulus, rather than a local,
Chinese-Remainder-separable count with multiplicative weights. The novelty lies in the mode
of access, not in the coordinate accessed.
\end{remark}

\section{Sharpness: the gap is $\Theta(1/M)$}\label{sec:sharp}

\begin{theorem}[Mersenne lower bound]\label{thm:mersenne}
For $M \ge 1$ and $r = 2^M-1$, $\;\lambda_1(r,M) \ge 1 - \frac{106}{M+1}$.
\end{theorem}
\begin{proof}[Proof sketch]
For $r = 2^M-1$ the dyadic orbit of $k=1$ consists, modulo $r$, of the binary place values
$1,2,4,\dots,2^{M-1}$ (and $2^M \equiv 1$). Using $1 - \cos u \le u^2/2$ for the small
angles and bounding the top few terms crudely by $2$,
\[
1 - \lambda_1 \;=\; \frac{1}{M+1}\sum_{t=0}^{M}\Bigl(1 - \cos\frac{2\pi 2^t}{r}\Bigr)
   \;\le\; \frac{1}{M+1}\sum_{t=0}^{M}\frac12\Bigl(\frac{2\pi 2^t}{r}\Bigr)^2 + O\!\left(\frac1{M+1}\right).
\]
Since $\sum_{t \le M} 4^t \le \tfrac43 4^M$ and $r \ge 2^M/2$, the right-hand side is an
absolute constant over $M+1$; carrying the constants through gives $106$.
\end{proof}

\begin{theorem}[$\Theta(1/M)$]
For $M \ge 2$ and $r = 2^M-1$,
$\;1 - \frac{106}{M+1} \le \lambda_1(r,M) \le 1 - \frac{1}{M+1}$.
\end{theorem}
\begin{proof}
Theorem~\ref{thm:mersenne} and Theorem~\ref{thm:gap} with $k = 1$.
\end{proof}

\begin{theorem}[Necessity of quadratic diffusion time]\label{thm:lower}
Let $M \ge 106$, $r = 2^M-1$, and let $n$ satisfy $154 n \le M(M+1)$. Then
$\round{1/p_n(r,M)} \ne r$.
\end{theorem}
\begin{proof}[Proof sketch]
Halving Theorem~\ref{thm:mersenne} gives $\mu_1 \ge 1 - \delta$ with
$\delta = \frac{53}{M+1} \le \tfrac12$. The elementary reverse bound
$e^{-2\delta} \le 1-\delta$ on $0 \le \delta \le \tfrac12$ yields
$\mu_1^n \ge e^{-2\delta n} = e^{-106n/(M+1)}$. Keeping only the two leading spectral terms,
$p_n(r,M) \ge \frac{1+\mu_1^n}{r}$. When $154 n \le M(M+1)$ this forces
$p_n > \frac{1}{r - 1/2}$, i.e.\ $1/p_n < r - \tfrac12$, so the rounding cannot return $r$.
\end{proof}

\begin{corollary}
With $M = \Theta(\log N)$, the number of diffusion steps required by this mechanism is
$\Theta((\log N)^2)$: sufficiency by Theorem~\ref{thm:main}, necessity by
Theorem~\ref{thm:lower}.
\end{corollary}

\section{Arithmetic payload}\label{sec:payload}

\begin{theorem}[Nontrivial square root splits $N$]\label{thm:sqrt}
Let $N \ge 2$ and $y \in \Z$ with $N \mid (y-1)(y+1)$, $N \nmid (y-1)$ and $N \nmid (y+1)$.
Then $d = \gcd(y-1,N)$ satisfies $d \mid N$ and $1 < d < N$.
\end{theorem}
\begin{proof}
$d \mid N$ is clear. If $d = 1$ then $y-1$ is coprime to $N$, forcing $N \mid y+1$, a
contradiction; if $d = N$ then $N \mid y-1$, also a contradiction.
\end{proof}

\begin{theorem}[Factorisation from an even order]
Let $N \ge 2$ and $b,m \ge 1$ with $N \mid b^{2m}-1$, $N \nmid b^m-1$, $N \nmid b^m+1$.
Then $\gcd(b^m-1,N)$ is a nontrivial divisor of $N$, computable by one Euclidean algorithm.
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:sqrt} with $y = b^m$, using $b^{2m}-1 = (b^m-1)(b^m+1)$.
\end{proof}

For $N = 143$, $b = 2$: $r = 60$, $b^{30} \equiv 12 \pmod{143}$, and
$\gcd(11,143) = 11$, giving $143 = 11\cdot 13$.

\section{The sealing barrier: aggregation cost}\label{sec:barrier}

The recovery theorem is unconditional, exact, and useless as an algorithm. It is worth
stating precisely why.

\begin{observation}[Spectral evaluation]
Evaluating $p_n(r,M) = \frac1r\sum_{k<r}\mu_k^n$ costs $\Theta(rM)$ arithmetic operations;
$r$ divides $\varphi(N)$ and is generically of size $\Theta(N)$, so this is exponential in
$\log N$ --- and the formula presupposes $r$.
\end{observation}

\begin{observation}[Operational evaluation]
Iterating $W_M$ requires a vector of $r$ numbers, updated $n = \Theta((\log N)^2)$ times at
cost $\Theta(rM)$ per step: $\Theta(r(\log N)^3)$ time and $\Theta(r)$ space.
\end{observation}

\begin{observation}[Physical realisations relocate the cost]
A device performing the diffusion in wall-clock time independent of the state-space size
must physically embody that state space: $\Theta(r)$ modes, cells, or degrees of freedom, so
its area or energy scales like $r$. The aggregation cost is conserved; only its currency
changes.
\end{observation}

This is the precise sense in which the mechanism is an \emph{informationally free but
computationally sealed} witness: the coordinate $r$ is recovered from one scalar by an exact
and provable rule, yet producing that scalar costs $\Theta(r)$ in some resource. A proof
that \emph{all} such spectral aggregates are sealed --- that no evaluation avoids
$\Theta(r)$-scale aggregation in every resource simultaneously --- is not established here
and remains the central open problem in this direction. A digital shortcut through
collisions among the dyadic residues $\{2^t \bmod r\}$ is likewise no help: it degenerates
to birthday-type or $p-1$-type search.

\section{Two sharp conjectures}

\begin{conjecture}[The dyadic deficiency constant is $2$]\label{conj:def}
For every $r \ge 2$, every $k \not\equiv 0 \pmod r$ and every $M$ with $r \le 2^M$,
\[
\sum_{t=0}^{M}\Bigl(1 - \cos\frac{2\pi k 2^t}{r}\Bigr) \;\ge\; 2,
\]
with equality only for $(r,k) = (2,1)$. Consequently $\lambda_k \le 1 - \frac{2}{M+1}$,
$\mu_k \le 1 - \frac{1}{M+1}$, and the sufficient step count improves from $8(M+1)^2$ to
$4(M+1)^2$.
\end{conjecture}

The doubling lemma produces a single far-arc crossing, worth deficiency $\ge 1$; but the
crossing is \emph{approached}, the previous doubling having exactly half the circle
distance, and that contributes a further deficiency that never vanishes. The missing factor
is a bookkeeping argument over consecutive doublings. Exhaustive search over all $(r,k)$
with $M \le 9$ shows the true infimum is exactly $2$; a single triple with deficiency $<2$
would falsify the conjecture.

\begin{conjecture}[Mersenne extremality]\label{conj:mers}
The limit $c^\star = \lim_{M\to\infty}\bigl(1-\lambda_1(2^M-1,M)\bigr)(M+1)$ exists and
equals approximately $3.3946$, and the minimal-gap profile over $r \le 2^M$ is attained
along Mersenne cycles.
\end{conjecture}

For $r = 2^M-1$ the dyadic orbit is exactly the binary place values, so the deficiency is a
truncated geometric series $\sum_t 4^t/r^2$ --- a self-similar quantity, which explains why
the numerics stabilise to five digits by $M = 12$. Theorem~\ref{thm:mersenne} already has
the right shape with constant $106$; closing the gap needs only sharper cosine control at
the top few frequencies $t \ge M-3$.

\section{Discussion and future work}

\paragraph{What is new.} A completely elementary route from a combinatorial statement about
doubling on a circle to a quantitative spectral gap; an \emph{exact} recovery statement for
an integer-valued arithmetic invariant from one real measurement, with a factor-of-two
rounding margin; and a matching lower bound fixing the diffusion time at
$\Theta((\log N)^2)$, so the cost profile is characterised rather than merely bounded.

\paragraph{Design principle.} On a cyclic group of unknown order $r$, adding lacunary
generators in geometric progression up to a known bound $2^M \ge r$ reduces mixing from
$\Theta(r^2)$ to $O((\log r)^2)$, and the return probability then reads off $r$ exactly ---
a reusable gadget wherever a cyclic period must be \emph{measured} rather than searched for.

\paragraph{Future directions.}
\begin{enumerate}
\item Prove Conjecture~\ref{conj:def}, halving the constant in the step count.
\item Prove Conjecture~\ref{conj:mers}, identifying $c^\star$ and the extremal family.
\item \emph{Lacunary base-$a$ walks:} replace $2^t$ by $a^t$; the escape argument survives
  with far arc $[r/(2a), r(1-1/(2a))]$ and threshold $2a\,d_r(x) < r$, suggesting an optimal
  trade-off between generator count and gap.
\item \emph{Non-cyclic groups:} extend to $(\Z/N\Z)^\times$ or to general finite abelian
  groups with a known exponent bound, running the far-arc argument in every cyclic component
  simultaneously.
\item \emph{Robustness:} quantify noise tolerance; the factor-of-two margin suggests the
  mechanism survives relative error of order $1/(4N^2)$, making precision a fourth currency
  in the cost accounting.
\item \emph{Aggregation-necessity theorem:} formulate and attack the claim that any
  evaluation of such a spectral aggregate must expend $\Theta(r)$ in time, space, area,
  energy or precision.
\end{enumerate}

